=== README.md
# billing-events

Subscription lifecycle for the billing service. Everything that happens to a subscription is a
`SubscriptionEvent` (`src/events.ts`), and three places consume those events:

- `src/subscription.ts` rebuilds a subscription's current state from its events.
- `src/audit.ts` turns an event into one line for the audit log.
- `src/notifier.ts` decides which emails an event triggers.

Each of them ends its `switch` with `assertNever`, so the compiler tells you where a new event type still
needs handling.

## Setup and tests

```
npm install
npm test            # node --test
npm run typecheck   # tsc --noEmit
```
=== src/assert-never.ts
/** Makes a `switch` over a union exhaustive: the compiler rejects the call while a case is still unhandled. */
export function assertNever(value: never): never {
  throw new Error(`Unhandled value: ${JSON.stringify(value)}`);
}
=== src/audit.ts
import { assertNever } from "./assert-never.ts";
import type { SubscriptionEvent } from "./events.ts";

/** One line for the audit log: timestamp, subscription id, event type, then the event's details. */
export function serializeAuditEntry(event: SubscriptionEvent): string {
  const entry = `${event.occurredAt} ${event.subscriptionId} ${event.type}`;
  const details = auditDetails(event);
  return details === "" ? entry : `${entry} ${details}`;
}

function auditDetails(event: SubscriptionEvent): string {
  switch (event.type) {
    case "subscription_started":
      return `plan=${event.plan}`;
    case "plan_changed":
      return `from=${event.from} to=${event.to}`;
    case "payment_failed":
      return `attempt=${event.attempt}`;
    case "payment_recovered":
      return "";
    case "subscription_canceled":
      return `reason=${JSON.stringify(event.reason)}`;
    default:
      return assertNever(event);
  }
}
